import { defineConfig } from "oxlint";
import core from "ultracite/oxlint/core";
import react from "ultracite/oxlint/react";
import vitest from "ultracite/oxlint/vitest";

export default defineConfig({
  env: core.env,
  extends: [core, react, vitest],
  // shadcn/ui components are generated by the shadcn CLI; keep them as upstream ships them.
  ignorePatterns: [...core.ignorePatterns, "**/dist-demo", "examples/*/src/components/ui"],
  // These rules' autofixes break this codebase.
  rules: {
    // Its fix is `toSorted()`, which needs ES2023; the package targets ES2020 / lib ES2022.
    "unicorn/no-array-sort": "off",
    // `for (const x of [...collection])` snapshots a set or array that the loop body mutates
    // (dispose/reset/leave remove entries); dropping the spread would skip items.
    "unicorn/no-useless-spread": "off",
    // `.at()` returns `T | undefined` under strict mode and doesn't exist on DOMRectList.
    "unicorn/prefer-at": "off",
    // `.dataset` only exists on HTMLElement/SVGElement, not the plain `Element`s scan.ts walks.
    "unicorn/prefer-dom-node-dataset": "off",
    // Its fix swaps `parseFloat` for `Number()`, but CSS values carry units: `Number("2px")` is NaN.
    "unicorn/prefer-number-coercion": "off",
  },
});
